package com.newzkl.platform.base.biz.order.infrastructure.dao.order;import com.baomidou.mybatisplus.core.mapper.BaseMapper;import com.newzkl.platform.base.biz.order.infrastructure.entity.OrderStateRecordDO;import com.newzkl.platform.base.biz.order.model.req.query.OrderStateRecordQuery;import com.newzkl.platform.base.common.core.mybatis.support.BaseLambdaQueryWrapper;import org.apache.ibatis.annotations.Mapper;/** * 订单状态记录表 Mapper 接口 * * @author sijiwang * @since 2026-01-30 */@Mapperpublic interface OrderStateRecordDAO extends BaseMapper<OrderStateRecordDO> {    default BaseLambdaQueryWrapper<OrderStateRecordDO> getLw(OrderStateRecordQuery query){        return new BaseLambdaQueryWrapper<OrderStateRecordDO>()                .notEmptyEq(OrderStateRecordDO::getSpuOrderId,query.getSpuOrderId())                ;    }}